{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2188-09-11 21:34:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand your G-tube clogged and you've been feeling really sick since then."
    },
    {
      "turn_number": 2,
      "time": "2188-09-11 21:35:00",
      "speaker": "Patient",
      "text": "Yes, it clogged yesterday. I tried flushing it, but it ripped and stomach contents spilled out."
    },
    {
      "turn_number": 3,
      "time": "2188-09-11 21:36:00",
      "speaker": "Doctor",
      "text": "I see. That must have been distressing. You started having nausea, vomiting, and abdominal pain after that?"
    },
    {
      "turn_number": 4,
      "time": "2188-09-11 21:37:00",
      "speaker": "Patient",
      "text": "Yes, nonstop. I’ve lost count of how many times I’ve vomited. And now there’s this burning rash where the fluid touched my skin."
    },
    {
      "turn_number": 5,
      "time": "2188-09-11 21:38:00",
      "speaker": "Doctor",
      "text": "That sounds like irritation from the tube contents. We’ll clean it and start treatment. Any fever or chills?"
    },
    {
      "turn_number": 6,
      "time": "2188-09-11 21:39:00",
      "speaker": "Patient",
      "text": "No, no fever. Just the pain and nausea."
    },
    {
      "turn_number": 7,
      "time": "2188-09-11 21:40:00",
      "speaker": "Doctor",
      "text": "Good. Your vitals are stable. We’ve checked your labs and found your potassium is a bit low, so we’re giving you some IV fluids and potassium."
    },
    {
      "turn_number": 8,
      "time": "2188-09-11 21:41:00",
      "speaker": "Patient",
      "text": "Okay. Will I be able to eat or feed through the tube soon?"
    },
    {
      "turn_number": 9,
      "time": "2188-09-11 21:42:00",
      "speaker": "Doctor",
      "text": "Not yet. The tube is damaged, so we’ll need to replace it. The interventional radiology team will do that tomorrow."
    },
    {
      "turn_number": 10,
      "time": "2188-09-11 21:43:00",
      "speaker": "Patient",
      "text": "Again? This is the second time in months."
    },
    {
      "turn_number": 11,
      "time": "2188-09-11 21:44:00",
      "speaker": "Doctor",
      "text": "I know it’s frustrating. We’ll use a larger tube this time to reduce the chance of clogging."
    },
    {
      "turn_number": 12,
      "time": "2188-09-12 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. The team replaced your GJ tube this morning with a 16 French one. It’s now in the right place."
    },
    {
      "turn_number": 13,
      "time": "2188-09-12 08:01:00",
      "speaker": "Patient",
      "text": "Is it safe to start feeds?"
    },
    {
      "turn_number": 14,
      "time": "2188-09-12 08:02:00",
      "speaker": "Doctor",
      "text": "We’ll start slowly tomorrow. Your stomach needs time to adjust after the procedure."
    },
    {
      "turn_number": 15,
      "time": "2188-09-12 08:03:00",
      "speaker": "Patient",
      "text": "What about the rash? It still burns."
    },
    {
      "turn_number": 16,
      "time": "2188-09-12 08:04:00",
      "speaker": "Doctor",
      "text": "We’ve started a cream called betamethasone and an antibiotic ointment to prevent infection. It should improve in a few days."
    },
    {
      "turn_number": 17,
      "time": "2188-09-13 09:00:00",
      "speaker": "Doctor",
      "text": "We’re starting your tube feeds today with a new formula called Osmolite 1.5. It’s easier on your stomach."
    },
    {
      "turn_number": 18,
      "time": "2188-09-13 09:01:00",
      "speaker": "Patient",
      "text": "Will this one cause less nausea?"
    },
    {
      "turn_number": 19,
      "time": "2188-09-13 09:02:00",
      "speaker": "Doctor",
      "text": "We hope so. We’ll go slow and monitor you closely. If you tolerate it, we’ll increase the rate."
    },
    {
      "turn_number": 20,
      "time": "2188-09-14 07:00:00",
      "speaker": "Doctor",
      "text": "Your stool test came back positive for C. difficile. That could be contributing to your nausea and loose stools."
    },
    {
      "turn_number": 21,
      "time": "2188-09-14 07:01:00",
      "speaker": "Patient",
      "text": "Again? I had that before."
    },
    {
      "turn_number": 22,
      "time": "2188-09-14 07:02:00",
      "speaker": "Doctor",
      "text": "Yes, it’s a recurrence. We’re starting oral vancomycin for 10 days to treat it."
    },
    {
      "turn_number": 23,
      "time": "2188-09-14 07:03:00",
      "speaker": "Patient",
      "text": "Will that help me feel better faster?"
    },
    {
      "turn_number": 24,
      "time": "2188-09-14 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, it should reduce the diarrhea and help your gut heal. We’ll keep monitoring your symptoms."
    },
    {
      "turn_number": 25,
      "time": "2188-09-15 08:30:00",
      "speaker": "Doctor",
      "text": "You’re doing well with the feeds. The vancomycin seems to be helping—your stools are less frequent."
    },
    {
      "turn_number": 26,
      "time": "2188-09-15 08:31:00",
      "speaker": "Patient",
      "text": "The rash is also less red. But I felt a gurgle in my tube this morning and then it stopped draining."
    },
    {
      "turn_number": 27,
      "time": "2188-09-15 08:32:00",
      "speaker": "Doctor",
      "text": "We’ll check it. Sometimes they can clog again, especially with formula changes."
    },
    {
      "turn_number": 28,
      "time": "2188-09-15 10:00:00",
      "speaker": "Doctor",
      "text": "I’m sorry, but the tube is clogged again. We’ll need to replace it."
    },
    {
      "turn_number": 29,
      "time": "2188-09-15 10:01:00",
      "speaker": "Patient",
      "text": "Again? This is so discouraging."
    },
    {
      "turn_number": 30,
      "time": "2188-09-15 10:02:00",
      "speaker": "Doctor",
      "text": "I understand. We’ll use an 18 French tube this time—larger to prevent clogging. The team will do it tomorrow."
    },
    {
      "turn_number": 31,
      "time": "2188-09-16 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—the new 18 French tube was placed successfully. It’s working well."
    },
    {
      "turn_number": 32,
      "time": "2188-09-16 08:01:00",
      "speaker": "Patient",
      "text": "Can we restart feeds?"
    },
    {
      "turn_number": 33,
      "time": "2188-09-16 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll restart Osmolite 1.5 at a low rate and increase as you tolerate it."
    },
    {
      "turn_number": 34,
      "time": "2188-09-17 07:30:00",
      "speaker": "Doctor",
      "text": "You’re tolerating the feeds well. Your nausea has improved, and your labs are stabilizing."
    },
    {
      "turn_number": 35,
      "time": "2188-09-17 07:31:00",
      "speaker": "Patient",
      "text": "That’s a relief. How long before I can go home?"
    },
    {
      "turn_number": 36,
      "time": "2188-09-17 07:32:00",
      "speaker": "Doctor",
      "text": "If this continues, likely in two days. We’ll finish your vancomycin course and make sure the tube stays open."
    },
    {
      "turn_number": 37,
      "time": "2188-09-17 07:33:00",
      "speaker": "Patient",
      "text": "Will I need to keep using this new formula?"
    },
    {
      "turn_number": 38,
      "time": "2188-09-17 07:34:00",
      "speaker": "Doctor",
      "text": "Yes, we think Osmolite 1.5 is better for your gastroparesis. We’ll send it home with you."
    },
    {
      "turn_number": 39,
      "time": "2188-09-18 08:00:00",
      "speaker": "Doctor",
      "text": "Your rash is improving. We’ll keep using the creams for a few more days."
    },
    {
      "turn_number": 40,
      "time": "2188-09-18 08:01:00",
      "speaker": "Patient",
      "text": "The betamethasone says not to use it long-term. Is that safe?"
    },
    {
      "turn_number": 41,
      "time": "2188-09-18 08:02:00",
      "speaker": "Doctor",
      "text": "Good question. We’ll stop it after two weeks—it can thin the skin. The Bactroban will continue for infection prevention."
    },
    {
      "turn_number": 42,
      "time": "2188-09-18 08:03:00",
      "speaker": "Patient",
      "text": "And the vancomycin?"
    },
    {
      "turn_number": 43,
      "time": "2188-09-18 08:04:00",
      "speaker": "Doctor",
      "text": "You’ll finish a 10-day course. We’re prescribing four more days to complete it at home."
    },
    {
      "turn_number": 44,
      "time": "2188-09-19 07:30:00",
      "speaker": "Doctor",
      "text": "You’re doing great. The tube is working, feeds are at goal, and your pain is controlled."
    },
    {
      "turn_number": 45,
      "time": "2188-09-19 07:31:00",
      "speaker": "Patient",
      "text": "Can I go home tomorrow?"
    },
    {
      "turn_number": 46,
      "time": "2188-09-19 07:32:00",
      "speaker": "Doctor",
      "text": "Yes, if all goes well. We’ll finalize your discharge plan today."
    },
    {
      "turn_number": 47,
      "time": "2188-09-19 07:33:00",
      "speaker": "Patient",
      "text": "Will I have help at home?"
    },
    {
      "turn_number": 48,
      "time": "2188-09-19 07:34:00",
      "speaker": "Doctor",
      "text": "Yes, home health will assist with wound care and tube management. They’ll teach your husband too."
    },
    {
      "turn_number": 49,
      "time": "2188-09-19 07:35:00",
      "speaker": "Patient",
      "text": "What about follow-up?"
    },
    {
      "turn_number": 50,
      "time": "2188-09-19 07:36:00",
      "speaker": "Doctor",
      "text": "Gastroenterology and oncology will see you soon. We’ll send records and prescriptions."
    },
    {
      "turn_number": 51,
      "time": "2188-09-20 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home today."
    },
    {
      "turn_number": 52,
      "time": "2188-09-20 08:01:00",
      "speaker": "Patient",
      "text": "I’m so glad. Thank you for fixing the tube and helping me feel better."
    },
    {
      "turn_number": 53,
      "time": "2188-09-20 08:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: use the creams as directed, finish the vancomycin, and keep using Osmolite 1.5."
    },
    {
      "turn_number": 54,
      "time": "2188-09-20 08:03:00",
      "speaker": "Patient",
      "text": "And flush the tube regularly?"
    },
    {
      "turn_number": 55,
      "time": "2188-09-20 08:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Flush with water before and after feeds and meds. Call if it clogs or the rash worsens."
    },
    {
      "turn_number": 56,
      "time": "2188-09-20 08:05:00",
      "speaker": "Patient",
      "text": "I will. And I’ll keep my appointments."
    },
    {
      "turn_number": 57,
      "time": "2188-09-20 08:06:00",
      "speaker": "Doctor",
      "text": "Perfect. We’re also continuing your regular meds: omeprazole, metoclopramide, gabapentin, and pain meds as needed."
    },
    {
      "turn_number": 58,
      "time": "2188-09-20 08:07:00",
      "speaker": "Patient",
      "text": "And Denosumab?"
    },
    {
      "turn_number": 59,
      "time": "2188-09-20 08:08:00",
      "speaker": "Doctor",
      "text": "Yes, resume your usual schedule. Oncology will manage that."
    },
    {
      "turn_number": 60,
      "time": "2188-09-20 08:09:00",
      "speaker": "Patient",
      "text": "Thank you for explaining everything."
    },
    {
      "turn_number": 61,
      "time": "2188-09-20 08:10:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Take care, and call if anything changes."
    },
    {
      "turn_number": 62,
      "time": "2188-09-20 08:11:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 63,
      "time": "2188-09-20 08:12:00",
      "speaker": "Doctor",
      "text": "The discharge nurse will go over wound care and give you supplies."
    },
    {
      "turn_number": 64,
      "time": "2188-09-20 08:13:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready."
    },
    {
      "turn_number": 65,
      "time": "2188-09-20 08:14:00",
      "speaker": "Doctor",
      "text": "We’ll also send instructions on how to clean the skin around the tube and change the dressing daily."
    },
    {
      "turn_number": 66,
      "time": "2188-09-20 08:15:00",
      "speaker": "Patient",
      "text": "Should I moisten the dressing before removing it?"
    },
    {
      "turn_number": 67,
      "time": "2188-09-20 08:16:00",
      "speaker": "Doctor",
      "text": "Yes, to avoid trauma. Use saline to dampen it first."
    },
    {
      "turn_number": 68,
      "time": "2188-09-20 08:17:00",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 69,
      "time": "2188-09-20 08:18:00",
      "speaker": "Doctor",
      "text": "And keep monitoring for signs of infection: increased redness, swelling, or pus."
    },
    {
      "turn_number": 70,
      "time": "2188-09-20 08:19:00",
      "speaker": "Patient",
      "text": "I’ll watch for that."
    },
    {
      "turn_number": 71,
      "time": "2188-09-20 08:20:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. We’re confident you’ll do well at home."
    },
    {
      "turn_number": 72,
      "time": "2188-09-20 08:21:00",
      "speaker": "Patient",
      "text": "I feel much better than when I came in."
    },
    {
      "turn_number": 73,
      "time": "2188-09-20 08:22:00",
      "speaker": "Doctor",
      "text": "That’s the goal. Take it easy, follow the plan, and we’ll see you in follow-up."
    },
    {
      "turn_number": 74,
      "time": "2188-09-20 08:23:00",
      "speaker": "Patient",
      "text": "I appreciate all your help."
    },
    {
      "turn_number": 75,
      "time": "2188-09-20 08:24:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Have a safe trip home."
    },
    {
      "turn_number": 76,
      "time": "2188-09-20 08:25:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 77,
      "time": "2188-09-20 08:26:00",
      "speaker": "Doctor",
      "text": "One last thing—your husband can call the on-call team if he has questions about tube care."
    },
    {
      "turn_number": 78,
      "time": "2188-09-20 08:27:00",
      "speaker": "Patient",
      "text": "He’ll be glad to know that."
    },
    {
      "turn_number": 79,
      "time": "2188-09-20 08:28:00",
      "speaker": "Doctor",
      "text": "We’re here to support you both."
    },
    {
      "turn_number": 80,
      "time": "2188-09-20 08:29:00",
      "speaker": "Patient",
      "text": "That means a lot."
    },
    {
      "turn_number": 81,
      "time": "2188-09-20 08:30:00",
      "speaker": "Doctor",
      "text": "Rest well, and take care."
    },
    {
      "turn_number": 82,
      "time": "2188-09-20 08:31:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 83,
      "time": "2188-09-20 08:32:00",
      "speaker": "Doctor",
      "text": "You’re all set. The nurse will bring your discharge papers shortly."
    },
    {
      "turn_number": 84,
      "time": "2188-09-20 08:33:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready to go."
    },
    {
      "turn_number": 85,
      "time": "2188-09-20 08:34:00",
      "speaker": "Doctor",
      "text": "Take care, and we’ll see you in clinic soon."
    }
  ],
  "summary": {
    "admission_start": "2188-09-11 21:34:00",
    "admission_end": "2188-09-20 16:00:00",
    "summary_paragraph": "A woman with metastatic breast cancer and refractory gastroparesis was admitted due to a clogged G-tube that ruptured, causing leakage of contents and a chemical skin rash. She developed worsening nausea, vomiting, and abdominal pain. A new 16 French GJ tube was placed, but it clogged again, requiring replacement with an 18 French tube. During admission, she was diagnosed with recurrent C. difficile infection, treated with oral vancomycin. Skin irritation around the tube site was managed with mupirocin and betamethasone cream. Tube feeds were resumed with Osmolite 1.5, which she tolerated well. She improved clinically, with resolution of symptoms and stable vitals, and was discharged home with services to complete her vancomycin course and continue home care.",
    "problems": [
      "Gastrostomy malfunction",
      "Enterocolitis due to Clostridium difficile, recurrent",
      "Secondary malignant neoplasm of liver and intrahepatic bile duct",
      "Secondary malignant neoplasm of bone",
      "Gastroparesis",
      "Anxiety disorder, unspecified",
      "Unspecified osteoarthritis, unspecified site",
      "Irritant contact dermatitis due to other chemical products",
      "Neoplasm related pain (acute) (chronic)",
      "Drug induced constipation",
      "Adverse effect of other opioids, initial encounter",
      "Hypothyroidism, unspecified",
      "Gastro-esophageal reflux disease without esophagitis",
      "Tachycardia, unspecified",
      "Acquired absence of other specified parts of digestive tract",
      "Personal history of malignant neoplasm of breast",
      "Personal history of antineoplastic chemotherapy"
    ]
  }
}
